<?php declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';$db=db();$e=fn($v)=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');$token=(string)($_GET['token']??'');$id=(int)($_GET['id']??0);$hash=hash('sha256',$token);$s=$db->prepare('SELECT s.*,c.id client_id,c.name client_name FROM client_portal_sessions s JOIN clients c ON c.id=s.client_id WHERE s.token_hash=? AND s.expires_at>NOW()');$s->execute([$hash]);$session=$s->fetch();if(!$session){http_response_code(403);exit('Invalid or expired portal link.');}$p=$db->prepare('SELECT * FROM client_projects WHERE id=? AND client_id=?');$p->execute([$id,$session['client_id']]);$project=$p->fetch();if(!$project){http_response_code(404);exit('Project not found.');}$m=$db->prepare('SELECT * FROM project_milestones WHERE project_id=? ORDER BY sort_order,id');$m->execute([$id]);$milestones=$m->fetchAll();$t=$db->prepare('SELECT t.*,m.name milestone_name FROM project_tasks t LEFT JOIN project_milestones m ON m.id=t.milestone_id WHERE t.project_id=? ORDER BY t.due_date IS NULL,t.due_date');$t->execute([$id]);$tasks=$t->fetchAll();$d=$db->prepare('SELECT * FROM project_documents WHERE project_id=? AND visibility="client" ORDER BY uploaded_at DESC');$d->execute([$id]);$docs=$d->fetchAll();$a=$db->prepare('SELECT a.*,m.name milestone_name FROM project_approvals a LEFT JOIN project_milestones m ON m.id=a.milestone_id WHERE a.project_id=? ORDER BY a.created_at DESC');$a->execute([$id]);$approvals=$a->fetchAll();$ac=$db->prepare('SELECT * FROM project_activity WHERE project_id=? ORDER BY created_at DESC LIMIT 30');$ac->execute([$id]);$activities=$ac->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=$e($project['name'])?></title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-5"><a href="index.php?token=<?=$e(urlencode($token))?>" class="text-decoration-none">← All Projects</a><div class="mt-3 mb-4"><h1 class="h2"><?=$e($project['name'])?></h1><p class="text-muted"><?=$e($project['project_number'])?> · <?=$e(str_replace('_',' ',$project['status']))?></p></div><div class="row g-4"><div class="col-lg-7"><div class="card mb-4"><div class="card-body"><h2 class="h5">Milestones & Tasks</h2><?php foreach($milestones as $milestone):?><div class="border-bottom py-3"><strong><?=$e($milestone['name'])?></strong><span class="badge text-bg-light float-end"><?=$e($milestone['status'])?></span><?php foreach($tasks as $task)if((int)$task['milestone_id']===(int)$milestone['id']):?><div class="ms-3 mt-2 small">• <?=$e($task['title'])?> — <?=$e($task['status'])?></div><?php endforeach;?></div><?php endforeach;?></div></div><div class="card mb-4"><div class="card-body"><h2 class="h5">Documents</h2><?php foreach($docs as $doc):?><div class="border-bottom py-2"><strong><?=$e($doc['title'])?></strong><div class="small text-muted"><?=$e($doc['file_name'])?></div></div><?php endforeach;if(!$docs):?><p class="text-muted">No client documents yet.</p><?php endif;?></div></div><div class="card"><div class="card-body"><h2 class="h5">Approvals</h2><?php foreach($approvals as $x):?><div class="border-bottom py-3"><div><strong><?=$e($x['approval_type'])?></strong> · <span class="badge text-bg-secondary"><?=$e($x['status'])?></span></div><div class="small text-muted mb-2"><?=$e($x['milestone_name']?:'Project-level')?> · <?=$e($x['created_at'])?></div><?php if($x['comment']):?><div class="small mb-2"><?=$e($x['comment'])?></div><?php endif;?><?php if($x['status']==='pending'):?><form method="post" action="approve.php" class="border rounded p-2 bg-light"><input type="hidden" name="token" value="<?=$e($token)?>"><input type="hidden" name="id" value="<?=$x['id']?>"><textarea class="form-control form-control-sm mb-2" name="comment" placeholder="Optional comment"></textarea><div class="d-flex gap-2"><button name="decision" value="approved" class="btn btn-sm btn-success">Approve</button><button name="decision" value="rejected" class="btn btn-sm btn-outline-danger">Reject</button></div></form><?php elseif(!empty($x['client_comment'])):?><div class="small text-muted">Client response: <?=$e($x['client_comment'])?></div><?php endif;?></div><?php endforeach;if(!$approvals):?><p class="text-muted">No approval requests.</p><?php endif;?></div></div></div><div class="col-lg-5"><div class="card"><div class="card-body"><h2 class="h5">Recent Activity</h2><?php foreach($activities as $x):?><div class="border-bottom py-2"><strong><?=$e($x['title'])?></strong><div class="small text-muted"><?=$e($x['created_at'])?> · <?=$e($x['actor_type'])?></div><?php if($x['description']):?><div class="small"><?=$e($x['description'])?></div><?php endif;?></div><?php endforeach;if(!$activities):?><p class="text-muted">No activity recorded yet.</p><?php endif;?></div></div></div></div></main></body></html>